
package dev.yinghuang.legacyforgebridge.repair322;
import com.google.gson.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;import java.util.*;import java.io.*;import static org.objectweb.asm.Opcodes.*;import static dev.yinghuang.legacyforgebridge.repair322.CoreVisualPass322.*;
/** Enumerates source map-backed eggs; never invents a numeric entity ID. */
public final class EggPass323 {
 record Egg(int id,String name,int base,int overlay,String entity){}
 static String key(String owner,String name,String desc){return owner+"."+name+desc;}
 static Object value(CoreVisualPass322 p,SourceValue v)throws Exception{AbstractInsnNode n=ArmorCompiler323.origin(v);if(n instanceof FieldInsnNode f&&f.getOpcode()==GETSTATIC){ClassNode c=p.classes.get(f.owner);if(c==null)throw new IllegalArgumentException("external numeric ID");for(FieldNode x:c.fields)if(x.name.equals(f.name)&&x.value!=null)return x.value;List<Object> vals=new ArrayList<>();for(MethodNode m:c.methods)for(AbstractInsnNode i:m.instructions)if(i instanceof FieldInsnNode x&&x.getOpcode()==PUTSTATIC&&x.name.equals(f.name)&&x.owner.equals(f.owner)){AbstractInsnNode prev=i.getPrevious();while(prev!=null&&prev.getOpcode()<0)prev=prev.getPrevious();SourceValue a=new SourceValue(1,prev);vals.add(ArmorCompiler323.constant(a));}if(vals.isEmpty()||new HashSet<>(vals).size()!=1)throw new IllegalArgumentException("ambiguous/dynamic numeric ID "+f.name);return vals.getFirst();}return ArmorCompiler323.constant(v);}
 static boolean population(CoreVisualPass322 p,String owner,String name,String desc,String mapOwner,String mapField,Set<String> seen){String key=key(owner,name,desc);if(!seen.add(key))return false;ClassNode c=p.classes.get(owner);if(c==null)return false;MethodNode m=c.methods.stream().filter(v->v.name.equals(name)&&v.desc.equals(desc)).findFirst().orElse(null);if(m==null)return false;boolean map=false,put=false,info=false;for(AbstractInsnNode n:m.instructions){if(n instanceof FieldInsnNode f&&f.getOpcode()==GETSTATIC&&f.owner.equals(mapOwner)&&f.name.equals(mapField))map=true;if(n instanceof MethodInsnNode q&&q.name.equals("put")&&q.desc.equals("(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;"))put=true;if(n instanceof MethodInsnNode q&&q.name.equals("<init>")&&q.desc.equals("(III)V"))info=true;}
  if(map&&put&&info)return true;
  for(AbstractInsnNode n:m.instructions)if(n instanceof MethodInsnNode q&&q.getOpcode()==INVOKESTATIC&&q.desc.startsWith("(Ljava/lang/Class;Ljava/lang/String;III")&&population(p,q.owner,q.name,q.desc,mapOwner,mapField,seen))return true;return false;
 }
 public static void apply(FeaturePass323 f)throws Exception {CoreVisualPass322 p=f.p;JsonObject creative=p.read("legacyforgebridge/creative-variants.json");JsonObject proof=new JsonObject();
  for(var item:p.content.getAsJsonArray("items")){JsonObject b=item.getAsJsonObject();String owner=b.get("sourceClass").getAsString();if(!"net/minecraft/item/ItemMonsterPlacer".equals(invoke(p.analyzer,"externalBase",owner)))continue;String id=b.get("id").getAsString(),ns=id.split(":")[0],path=id.split(":",2)[1];try{
   ClassNode source=p.classes.get(owner);FieldInsnNode map=null;for(MethodNode m:source.methods)if(Set.of("func_150895_a","getSubItems").contains(m.name))for(AbstractInsnNode n:m.instructions)if(n instanceof FieldInsnNode q&&q.getOpcode()==GETSTATIC&&q.desc.contains("Map"))map=q;if(map==null)throw new IllegalArgumentException("no source creative egg map");TreeMap<Integer,Egg> eggs=new TreeMap<>();
   for(ClassNode c:p.classes.values())for(MethodNode m:c.methods){if((m.access&(ACC_ABSTRACT|ACC_NATIVE))!=0)continue;Frame<SourceValue>[] frames;try{frames=new Analyzer<>(new SourceInterpreter()).analyze(c.name,m);}catch(Exception ignored){continue;}for(int i=0;i<m.instructions.size();i++)if(m.instructions.get(i) instanceof MethodInsnNode q&&q.getOpcode()==INVOKESTATIC&&q.desc.equals("(Ljava/lang/Class;Ljava/lang/String;III)V")&&population(p,q.owner,q.name,q.desc,map.owner,map.name,new HashSet<>())){Frame<SourceValue> fr=frames[i];int top=fr.getStackSize();try{Object entity=value(p,fr.getStack(top-5)),name=value(p,fr.getStack(top-4)),eid=value(p,fr.getStack(top-3)),bg=value(p,fr.getStack(top-2)),fg=value(p,fr.getStack(top-1));if(!(entity instanceof Type t)||!(name instanceof String str))continue;Egg e=new Egg(((Number)eid).intValue(),str,((Number)bg).intValue(),((Number)fg).intValue(),t.getInternalName());if(e.id<0||e.id>65535)throw new IllegalArgumentException("ID range");Egg prior=eggs.putIfAbsent(e.id,e);if(prior!=null&&!prior.equals(e))throw new IllegalArgumentException("duplicate source ID");}catch(Exception x){f.fail(id,"egg-site/"+c.name+":"+i,x);}}}
   if(eggs.isEmpty())throw new IllegalArgumentException("egg registrations not proven");
   for(String texture:List.of("spawn_egg","spawn_egg_overlay")){try(InputStream in=EggPass323.class.getResourceAsStream("/legacyforgebridge/platform1710/"+texture+".png")){if(in==null)throw new IllegalArgumentException("verified vanilla egg sprite unavailable");p.bytes("assets/"+ns+"/textures/item/lfb_egg323/"+texture+".png",in.readAllBytes());}}
   String template="lfb_egg323/"+path;JsonObject model=new JsonObject(),tx=new JsonObject();model.addProperty("parent","minecraft:item/generated");tx.addProperty("layer0",ns+":item/lfb_egg323/spawn_egg");tx.addProperty("layer1",ns+":item/lfb_egg323/spawn_egg_overlay");model.add("textures",tx);p.write("assets/"+ns+"/models/item/"+template+".json",model);
   JsonArray metas=new JsonArray(),details=new JsonArray();for(Egg egg:eggs.values()){String out="lfb_meta/"+path+"/"+egg.id;JsonObject def=new JsonObject(),leaf=new JsonObject();leaf.addProperty("type","minecraft:model");leaf.addProperty("model",ns+":item/"+template);JsonArray tints=new JsonArray();for(int rgb:new int[]{egg.base,egg.overlay}){JsonObject t=new JsonObject();t.addProperty("type","minecraft:constant");t.addProperty("value",rgb&0xffffff);tints.add(t);}leaf.add("tints",tints);def.add("model",leaf);p.write("assets/"+ns+"/items/"+out+".json",def);obj(obj(p.iconBook,"items"),id).addProperty(""+egg.id,ns+":"+out);String nameKey="lfb.egg323."+ns+"."+path+"."+egg.id;obj(obj(p.nameBook,"items"),id).addProperty(""+egg.id,nameKey);name(p,egg,nameKey);metas.add(egg.id);details.add(G.toJsonTree(egg));}
   obj(creative,"items").add(id,metas);proof.add(id,details);System.out.println("SOURCE_EGGS "+id+" variants="+eggs.size());
  }catch(Exception e){f.fail(id,"eggs",e);}}
  p.write("legacyforgebridge/creative-variants.json",creative);p.write("legacyforgebridge/item-names.json",p.nameBook);f.manifest.add("eggs",proof);
 }
 static void name(CoreVisualPass322 p,Egg e,String key)throws Exception {try(var dirs=java.nio.file.Files.walk(p.stage.resolve("assets"))){for(var file:dirs.filter(v->v.toString().replace('\\','/').contains("/lang/")&&v.toString().endsWith(".json")).toList()){JsonObject lang=JsonParser.parseString(java.nio.file.Files.readString(file)).getAsJsonObject();String match=null;for(var n:lang.entrySet())if(n.getKey().endsWith("."+e.name+".name")&&n.getKey().toLowerCase(Locale.ROOT).contains("entity")){if(match!=null&&!match.equals(n.getValue().getAsString())){match=null;break;}match=n.getValue().getAsString();}if(match==null)match=e.name;{String locale=file.getFileName().toString();String finalName=locale.startsWith("zh")?match+" 生成蛋":match+" Spawn Egg";lang.addProperty(key,finalName);p.write(p.stage.relativize(file).toString().replace('\\','/'),lang);}}}}
}
